{
  "events": [
    {
      "key": "axel_request",
      "choices": [
        {
          "index": 3,
          "label": "150골드로 운송을 준비하고 루나와 의뢰를 나눠 맡는다",
          "result": "루나와 상의하여 효율적인 운송 경로를 확보했습니다. 150골드와 물약 1개를 지급받고 루나의 기억 카드를 획득했습니다. 루나는 고개를 끄덕이며 다음 의뢰를 준비합니다."
        }
      ]
    },
    {
      "key": "axel_stolen_notice",
      "choices": [
        {
          "index": 3,
          "label": "100골드로 수색을 준비하고 크리스와 지나간 흔적을 구분한다",
          "result": "크리스와 협력하여 현장의 미세한 흔적을 추적하기 시작했습니다. 100골드와 물약 1개를 지급받고 크리스의 기억 카드를 획득했습니다. 크리스는 입꼬리를 올리며 수색 경로를 가리킵니다."
        },
        {
          "index": 4,
          "label": "180골드로 기록을 대조하고 카즈마와 청구할 몫을 나눈다",
          "result": "카즈마와 함께 꼼꼼하게 장부상의 수치를 대조했습니다. 180골드를 지불하고 카즈마의 기억 카드를 획득했습니다. 카즈마는 만족스러운 듯 계산서를 챙깁니다."
        }
      ]
    },
    {
      "key": "axel_blast_site",
      "choices": [
        {
          "index": 3,
          "label": "160골드로 표식을 마련하고 위즈와 대피 통로부터 살핀다",
          "result": "위즈의 조언에 따라 안전한 폭발 지점과 대피로를 확보했습니다. 160골드와 물약 1개를 지급받고 위즈의 기억 카드를 획득했습니다. 위즈는 안경을 고쳐 쓰며 수치를 확인합니다."
        }
      ]
    },
    {
      "key": "axel_shop_ledger",
      "choices": [
        {
          "index": 3,
          "label": "160골드로 분류 용품을 마련하고 위즈와 작은 고장부터 나눈다",
          "result": "분류 용품을 사용하여 마도구의 고장 정도를 체계적으로 정리했습니다. 160골드를 지불하고 위즈의 기억 카드를 획득했습니다. 위즈는 꼼꼼하게 분류된 물건들을 살핍니다."
        }
      ]
    }
  ]
}
